            if s[curr_A] == 'A':
                curr_A += ceil(n+1)
                set_count_A += 1
            else:
                curr_B += ceil(n+1)
                set_count_B += 1

            if (set_count_A > set_count_B):
                return 'A'
            elif (set_count_B > set_count_A):
                return 'B'

        if (curr_A >= n) and (curr_B < n):
            return 'A'
        elif (curr_B >= n) and (curr_A < n):
            return 'B'

        for i in range(n-1, -1, -ceil(n+1)):
            if s[i] == 'A':
                curr_A += ceil(n+1)
                set_count_A += 1
            else:
                curr_B += ceil(n+1)
                set_count_B += 1

            if (set_count_A > set_count_B):
                return 'A'
            elif (set_count_B > set_count_A):
                return 'B'

    for _ in range(t):
        n = int(input())
        s = input()
        result = dfs(n, s)
