def solve(n):
    def recurse(k1, k2, m, n):
        if (m <= 0) | (n == 0): 
            return 0

        min_count_k = n // k1
        max_count_k = n // (k1 + 1)
        best_response_win = float('-inf')

        for count_k in range(min_count_k, max_count_k+1):
            player_move_value = min(k2 * count_k + m-1, n)

            new_min_possible_m_outcome = player_move_value - ((player_move_value -1)//k2) * k1

            min_winning_probability = 0
            for i in range(int(new_min_possible_m_outcome), int(player_move_value)): 
                if recurse(k1, k2 + (i // count_k*(count_k == m)), new_min_possible_m_outcome - i, n - player_move_value) == True: # Alice has a winning strategy given this scenario
                    min_winning_probability = 1 
                    break            
            if new_min_possible_m_outcome < best_response_win:
                print("Alice")
            else:
                max_count_k = count_k

        for j in range(k2 // (m+1), k2):
            if n % j == 0: # this would lead Bob to win by reducing the board
                return True
        if max_count_k >= min_count_k:         
        	best_response_win=max(best_response_win, recurse(k1, k2 + (n//max_count_k)*(max_count_k==m), m - (k2+1) // count_k * count_k , n - n//max_count_k*max_count_k))
            return best_response_win >= 0.55
        else:
            print("Bob")
            return False

