        ans = [-1] * (n-1) + [m+1]
        last = [0]
        for i,p in enumerate(nums, 1):
            if len(heap) < n:
                heapq.heappush(heap, (-p,-len(last)))
                last.append(-last[-1])
            else:
                heapq.heappushpop(heap, (p,last.pop()))
            if len(last) <= n-1 and not heap or  -heap[0][0] != p:
                ans[-i] = i
        print(' '.join(map(str,ans)))

