def solve():
    n, s, r = map(int, input().split())

    # Initialize result list for each test case
    res = []

    # Function to check if a number can be obtained by summing elements in the current res list
    def valid(num):
        for i in range(1 << len(res)):
            temp_sum = 0
            for j in range(len(res)):
                if (i & (1 << j)) != 0:
                    temp_sum += res[j]
            if temp_sum == num:
                return True
        return False

    # Generate all possible sums of elements from 1 to 6, not exceeding the maximum number s
    for value in range(max(s - r + 1, 1), (s // n) + 2):

        # Check if a number can be obtained from res list by adding up its elements
        if valid(value):

            # Add the value to res list n times to meet the condition: sum of res is s and sum without the largest element is r
            while len(res) < n:
                res.append(value)

    return ' '.join(map(str, res))

