def solve(a: List[int]) -> int:
    n = len(a)
    b = [(abs(x - a[0]), x) for x in a[1:]]

    for i in range(n-2):
        diff, ele = max(b)
        temp_diff = (ele + abs(diff)) // 2
        if temp_diff > 0:
            b.remove((diff, ele))
            b.append((abs(ele - (a[0] + temp_diff)), a[0] + temp_diff))

    return a[0] + max([x for _, x in sorted(b)])

