        n = int(input())
        a = list(map(int, input().split()))

        for i in range(n):
            b = binary_representation(a[i])
            min_i = i
            max_i = i

            # Find max and min indices 
            for j in range(n):
                if (a[j] & (1 << 30)) > (a[min_i] & (1 << 30)):
                    min_i = j

                elif (a[j] & (1 << 30)) < (a[max_i] & (1 << 30)):
                    max_i = j
            # Swap the bits at these indices 
            for b_j in range(len(b)):
                if b[min_i][b_j] != b[max_i][b_j]:
                    a[min_i] ^= 1 << (len(b) - b_j - 1)
                    a[max_i] ^= 1 << (len(b) - b_j - 1)

        ans = 0
        for i in range(30):
            curr = sum((a[j] & 1 << i) > 0 for j in range(n))
            if curr == n:
                bits_set = 0
            elif curr == 0:
                bits_clear = 0
            else:
                # If there are both set and clear, we have some choices
                # Let's max out the number of 1s by swapping between these two bins
                bits_set = i + 1
                bits_clear = 30 - i

            ans |= (bits_set << i)

        print(ans)

