    seen = set()
    for elm in arr:
        seen.add(elm)

    def is_permutation(n):
        """Check if a number can be expressed as sum of distinct elements within the range [1,n]"""
        total_sum = (n * (n+1)) // 2
        target_sum = s + (m - len(seen))

        for num in range(1, n+1):
            if num not in seen and total_sum - ((num + (num*(num-1))//2) >= target_sum):
                return True
        return False

    max_n = m + s
    while is_permutation(max_n):
        if (max_n * (max_n + 1)) // 2 == s + (m - len(seen)):
            print("YES")
            return
        max_n += 1
    print("NO")

