        left = 0
        right = len(s) - 1
        while left < right:
            if s[left] != s[right]:
                right -= 1
            else:
                left += 1
                right -= 1
        return ''.join(s)

    output_list = []
    for string in input_data:
        odd_string = ''
        even_string = ''
        for idx, char in enumerate(string):
            if idx % 2 == 0:
                even_string += char * 2
            else:
                odd_string += char
        reordered_even_chars = reorder(even_string)
        output_list.append(reordered_even_chars + odd_string + reordered_even_chars[::-1])

    return '\n'.join(output_list)

