def solve():
    n = int(input())
    for _ in range(n):
        s = input()
        half_list = []
        extra_chars = []

        # Make a list of characters appearing an odd number of times and add the rest as one less repetition than before.
        for char in set(s):
            count = s.count(char)
            if count % 2 == 0:
                half_list.extend([char, char] * count // 2)
            else:
                extra_chars.append([char] + [char]* ((count-1)//2)*2)

        # Add characters from the end of the string first.
        output = []
        while half_list or any(extra_chars):
            if not half_list:
                output.extend(extra_chars.pop(0))
            elif not extra_chars:
                output.append(half_list.pop() * 2)
            else:
                left_half_char = half_list[-1]
                right_extra_char = ''.join(extra_chars[0])[0]

                # Prefer to add a character from the end, unless it's the same as the last in the middle of the string; then prefer the middle one.
                if right_extra_char != left_half_char or not extra_chars:
                    half_list.pop()
                    output.append(left_half_char * 2)
                    continue
                else:
                    extra_chars[0] = ''.join(extra_chars[0])[1:]
                output.append(right_extra_char * 2)

        print(''.join(output))

