def solve():
    n = int(input())
    nums = list(map(int, input().split()))

    ones = [0]
    for num in nums:
        if num == 1: ones.append(ones[-1] + 1)
        else: ones.append(ones[-1])

    q = deque()
    ans = 0
    for i in range(n):
        while len(q) > 0 and ones[i] >= ones[q[-1]]:
            q.pop()
        if len(q) == 0 or ones[i] <= ones[q[0]]:
            q.append(i)
            continue

        ans += 1 + (ones[i] - ones[q[0]])

        i = q.popleft()

    return ans

