def solve():
    t = int(input())

    for _ in range(t):
        n = int(input())
        mapping = {}

        numbers = list(map(int, input().split()))
        letters = input()

        # We use a priority queue (from the heapq module) to find the number we want to map
        pq = [(number, i) for i, number in enumerate(set(numbers))]
        heapq.heapify(pq)

        for letter, number in zip(letters, numbers):
            while True:
                num, idx = heapq.heappop(pq)
                if num == number:
                    mapping[num] = letter
                    break

        # We check if all numbers are mapped correctly
        for number in set(numbers):
            if len(mapping) < number or mapping[number] != letters[numbers.index(number)]:
                print("NO")
                break
        else:
            print("YES")

