    def dfs(graph, start):
        unvisited = set(graph.keys()) 
        visited, stack = set(), [start]

        while stack:
            vertex = stack.pop()
            if vertex not in visited:
                visited.add(vertex)
                for neighbour in graph[vertex]:
                    if neighbour[0] in unvisited:unvisited.remove(neighbour[0])
                    stack.append(neighbour[1])

        return len(unvisited)

