def generate_chain(n):
    chain = [list(range(1, n + 1))]
    for _ in range(n - 1):
        swapped = False
        k = len(chain[-1])
        for i in range(k):
            if chain[-1][i] == (len(chain[-1]) - i):
                temp = chain.pop()
                temp[i], temp[k-1] = temp[k-1], temp[i]
                chain.append(temp)
                swapped = True
                break
        if not swapped:
            raise ValueError("No valid chain can be generated")
    return chain

