        next_index = get_next_index(i)
        if n % 2 != 0 or (n >= 3 and next_index <= n//2 + 1):
            solve(n - 1 if next_index is not None else n, result + [i + 7 if i == 2 else i + 1], next_index or i)
        elif n >= 2:
            solve(n - 1, result + [n // 2 * 2 + 1])
        print(*result)

