def solve():
    n = int(input())
    d = 2
    while (n // d) ** 0.5 != floor((n // d) ** 0.5):
        d += 1
    d *= 2

    res_permutation = []

    for multiple in range(1, floor(n / d)):
        if n % (d * multiple) == 0:
            res_permutation.extend([multiple*d, multiple*d + 1])

    remaining_elements_left = set(range(multiple*2+1,n))

    while len(res_permutation) < n:
        i = len(res_permutation)
        new_number = list(remaining_elements_left)[int(len(remaining_elements_left)/2)]
        if new_number > d*multiple + 1:
            break
        else:
           res_permutation.insert(i,new_number)
        remaining_elements_left.remove(new_number)

    permutation_with_zero = [0]+res_permutation

    return ' '.join(str(x) for x in([d,] + permutation_with_zero))

